#!/usr/bin/env sh
#
# Usage:
#   test/brew-replay.sh formula|cask <list>
#
# The list holds one formula or cask per line, or is a brew-install.sh or brew-cask-install.sh generated by backup/macos.sh.

set -eu

kind=$1
list=$2
failures=

while read -r line
do
    name=${line##* }
    [ -n "$name" ] || continue

    echo "==> brew install --$kind $name"
    brew install "--$kind" "$name" < /dev/null || failures="$failures $name"
done < "$list"

if [ -n "$failures" ]
then
    echo "Failed:$failures" >&2
    exit 1
fi
